            login_page,
            login_submit,
            profile,
            regular_profile])
        .mount("/", FileServer::from(relative!("static")))
        .register("/", catchers![unauth])
        .attach(Template::fairing())
        .configure(rocket::Config {
            address: std::net::IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED),
            ..rocket::Config::release_default()
        })
}
