from pwn import *
import json

# Set up logging
context.log_level = 'debug'

# Connect to the server
conn = remote('crypto.chal.csaw.io', 8000)

def recv_until_json():
    data = b""
    while True:
        try:
            c = conn.recv(1)
            data += c
            if c == b'}':
                try:
                    return json.loads(data.decode())
                except:
                    continue
        except EOFError:
            break
    return None

# First request to see what we get
response = recv_until_json()
print("Initial response:", response)

# Send a request to view admin profile
admin_req = {
    "action": "view_profile",
    "user": "admin"
}
conn.sendline(json.dumps(admin_req).encode())
admin_response = recv_until_json()
print("\nAdmin profile response:", admin_response)

conn.close()

